import{_ as e,o as i,c as n,a3 as o}from"./chunks/framework.BwzYn71E.js";const _=JSON.parse('{"title":"Equivalence Relations Between Four Types of Uniformity","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"四种均匀性的等价关系","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0UWq18LU5z08cMqBDGHmT2","scope":"page"}},"headers":[],"relativePath":"src/page-0UWq18LU5z08cMqBDGHmT2.md","filePath":"logistics/src/page-0UWq18LU5z08cMqBDGHmT2.md","lastUpdated":null}'),a={name:"src/page-0UWq18LU5z08cMqBDGHmT2.md"};function r(p,t,l,c,s,m){return i(),n("div",null,[...t[0]||(t[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="四种均匀性的等价关系" aria-hidden="true"></span><h1 id="equivalence-relations-between-four-types-of-uniformity" tabindex="-1">Equivalence Relations Between Four Types of Uniformity <a class="header-anchor" href="#equivalence-relations-between-four-types-of-uniformity" aria-label="Permalink to &quot;Equivalence Relations Between Four Types of Uniformity&quot;">​</a></h1><blockquote><p>Source page ID: <code>0UWq18LU5z08cMqBDGHmT2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0UWq18LU5z08cMqBDGHmT2" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Definitions with unified notation:</p><p>Bresenham-M uniformity: for all n in Z+, |S_cum(n) - d * n| &lt; M.</p><p>Beatty-M uniformity: for all i,j in Z+, |S_cum(i,j) - (j-i) * d| &lt; M.</p><p>Here S_cum(i,j) = S_cum(j) - S_cum(i).</p><p>Cipolla-M item-count uniformity: sup_n(S_cum(n) - d * n) - inf_n(S_cum(n) - d * n) &lt; M.</p><p>Cipolla-M time uniformity: sup_n(t_n - n * T_avg) - inf_n(t_n - n * T_avg) &lt; M.</p><p>Note T_avg = 1/d.</p><p>Theorem 1: Bresenham-M uniformity is equivalent to Beatty-2M uniformity: implication both ways, constant factor 2.</p><p>Proof:</p><p>(=&gt;): |S_cum(j) - j * d| &lt; M and |S_cum(i) - i * d| &lt; M, so:</p><p>|S_cum(i,j) - (j-i)d| &lt;= |S_cum(j)-j * d| + |S_cum(i)-i * d| &lt; 2M.</p><p>(&lt;=): Set i=1 to obtain Bresenham-M uniformity.</p><p>Theorem 2: Beatty-M uniformity is equivalent to Cipolla-M item-count uniformity, with the same constant.</p><p>Proof:</p><p>(=&gt;): Beatty-M gives |E(i) - E(j)| = |S_cum(i,j) - (j-i)d| &lt; M for any two deviations, hence range &lt; M.</p><p>(&lt;=): A range &lt; M implies |E(j) - E(i)| &lt; M for every i,j, namely |S_cum(i,j) - (j-i)d| &lt; M.</p><p>Theorem 3: Cipolla-M item-count uniformity is equivalent to Cipolla-(M/d + 1) time uniformity: implication both ways, with converted constants.</p><p>Proof:</p><p>(=&gt;): Since S_cum(n) = k when t_k &lt;= n &lt; t_{k+1}, we have t_k - k * T_avg = T_avg(k * d - t_k * d) = (1/d)(k - S_cum(t_k)).</p><p>Using the dual relation between t_n - n/d and S_cum(n) - n * d, one can prove:</p><p>sup_n(t_n - n/d) - inf_n(t_n - n/d) &lt;= (1/d) * M.</p><p>(&lt;=): For n in [t_k, t_{k+1}), S_cum(n) = k, giving:</p><p>t_k - k * T_avg &lt;= n * T_avg - S_cum(n) * T_avg &lt; t_{k+1} - k * T_avg = (t_{k+1} - (k+1)T_avg) + T_avg.</p><p>Thus time uniformity =&gt; item-count uniformity, with M_item &lt;= d * M_time + 1.</p><p>Proof by madSUN, correctness reviewed by multiple group members, standardized terminology by jnk.</p><p>Translation note: The theorem statements, factors, indices and proof equalities are retained as written; potential mathematical inconsistencies have not been silently repaired.</p></div>',1)])])}const d=e(a,[["render",r]]);export{_ as __pageData,d as default};
